UPDATE REP_PROD_BONUS_REGISTER as A, ( select ID, PROD_ID, BONUS_REGISTER_DATE, BONUS_DEALT_DATE, UNIT_BONUS_AMT, INPUT_TYPE, INPUT_USER, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ,STATUS
,BONUSMODE
from ( select TEMP.* from (
SELECT #{item.id,jdbcType=CHAR} ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.bonusRegisterDate,jdbcType=DATE} BONUS_REGISTER_DATE, #{item.bonusDealtDate,jdbcType=DATE} BONUS_DEALT_DATE, #{item.unitBonusAmt,jdbcType=DECIMAL} UNIT_BONUS_AMT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} INPUT_USER, #{item.adapterId,jdbcType=VARCHAR} ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME ,#{item.status,jdbcType=TIMESTAMP} STATUS
,#{item.bonusmode,jdbcType=VARCHAR} BONUSMODE
FROM dual
) TEMP ) de ) AS B set A.ID = B.ID, A.BONUS_DEALT_DATE = B.BONUS_DEALT_DATE, A.UNIT_BONUS_AMT = B.UNIT_BONUS_AMT, A.INPUT_TYPE = B.INPUT_TYPE, A.INPUT_USER = B.INPUT_USER, A.ADAPTER_ID = B.ADAPTER_ID, A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME ,A.STATUS = B.STATUS
,A.BONUSMODE = B.BONUSMODE
where A.PROD_ID = B.PROD_ID AND A.BONUS_REGISTER_DATE = B.BONUS_REGISTER_DATE; insert into REP_PROD_BONUS_REGISTER(ID, PROD_ID, BONUS_REGISTER_DATE, BONUS_DEALT_DATE, UNIT_BONUS_AMT, INPUT_TYPE, INPUT_USER, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ,STATUS
,BONUSMODE
) select ID, PROD_ID, BONUS_REGISTER_DATE, BONUS_DEALT_DATE, UNIT_BONUS_AMT, INPUT_TYPE, INPUT_USER, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ,STATUS
,BONUSMODE
from ( select TEMP.* from (
SELECT #{item.id,jdbcType=CHAR} ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.bonusRegisterDate,jdbcType=DATE} BONUS_REGISTER_DATE, #{item.bonusDealtDate,jdbcType=DATE} BONUS_DEALT_DATE, #{item.unitBonusAmt,jdbcType=DECIMAL} UNIT_BONUS_AMT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} INPUT_USER, #{item.adapterId,jdbcType=VARCHAR} ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME ,#{item.status,jdbcType=TIMESTAMP} STATUS
,#{item.bonusmode,jdbcType=VARCHAR} BONUSMODE
FROM dual
) TEMP where not exists (select 1 from REP_PROD_BONUS_REGISTER CII where CII.PROD_ID = TEMP.PROD_ID AND CII.BONUS_REGISTER_DATE = TEMP.BONUS_REGISTER_DATE) ) de ;
